    assertPriority(rows(restored)[0], 'Normal');
    assertPriority(rows(restored)[1], 'Low');
    await server.stop();
    server = undefined;
    server = await startServer(dbPath);
    assert.equal(await html('/projects/1'), restored);
  } finally {
